# Runtime v2 · CL CompositionLocal và slot API (chương mới)
# Nguồn: "Locally scoped data with CompositionLocal" (developer.android.com, đọc 2026-11-23); CompositionLocal.kt, GapComposer.kt (skipping) @296313a4;
# Jetpack Compose 1.3 Essentials Ch.21 (CompLocalDemo, cây Composable1–8), Ch.22 (slot API, SlotDemo).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.locals ----------------
    m = lambda k, vi, en=None: a('m.locals.' + k, vi, en)
    m('title', 'Đổi giá trị của CompositionLocal: ai recompose?', 'Changing a CompositionLocal value: who recomposes?')
    m('overview', 'Một cây composable: `C1` có hai nhánh. Nhánh `C2 → C4 → C6`; nhánh kia bọc trong `CompositionLocalProvider(LocalColor provides …)` rồi `C3 → C5 → C7, C8`. `C3` và `C8` đọc `LocalColor.current`; `C6` cũng đọc nhưng ở ngoài provider. Bật công tắc "dark" để đổi màu được cung cấp, rồi so hai cách tạo LocalColor.', 'A composable tree: `C1` has two branches. One branch is `C2 → C4 → C6`; the other is wrapped in `CompositionLocalProvider(LocalColor provides …)`, then `C3 → C5 → C7, C8`. `C3` and `C8` read `LocalColor.current`; `C6` reads it too but outside the provider. Flip the "dark" switch to change the provided colour, then compare the two ways of creating LocalColor.')
    m('wrapup', 'Giá trị của CompositionLocal đi xuống theo cây, chỉ trong nhánh bên dưới provider gần nhất; ra ngoài nhánh đó là giá trị mặc định.\nKhi giá trị được cung cấp đổi: `compositionLocalOf` chỉ invalidate những chỗ đã đọc `.current`; còn `staticCompositionLocalOf` không theo dõi lần đọc, nên recompose toàn bộ content của provider. Static rẻ khi giá trị gần như không đổi (Context, font loader), nhưng đắt khi giá trị đổi thường xuyên.\nQuy tắc dễ nhớ: giá trị hay đổi thì `compositionLocalOf`; gần như không bao giờ đổi thì `staticCompositionLocalOf`.',
      "A CompositionLocal value flows down the tree, only within the branch below the nearest provider; outside that branch it is the default.\nWhen the provided value changes: `compositionLocalOf` only invalidates the places that read `.current`; `staticCompositionLocalOf` does not track reads, so it recomposes the provider's whole content. Static is cheap when the value almost never changes (the Context, font loaders), but expensive when it changes often.\nRule of thumb: values that change often use `compositionLocalOf`; values that almost never change use `staticCompositionLocalOf`.")
    m('simp.1', 'Mô phỏng chỉ đếm composable trong content của provider (C3, C5, C7, C8); C1 cũng chạy lại vì nó đọc `dark`, và C2 được skip. Tên màu (Peach, Brown) là minh họa.', 'The simulation only counts composables in the provider\'s content (C3, C5, C7, C8); C1 also re-runs because it reads `dark`, and C2 is skipped. Colour names (Peach, Brown) are illustrative.')
    m('simp.2', 'Trong app thật, đổi chế độ tối là một lần đổi cấu hình (theo `isSystemInDarkTheme()`). Site dùng một state `dark` để giữ ví dụ gói gọn trong một lượt recompose.',
      'In a real app, switching dark mode is a configuration change (following `isSystemInDarkTheme()`). The site uses a `dark` state to keep the example within a single recomposition.')
    m('ctl.hint', 'Chạy với compositionLocalOf, rồi đổi sang staticCompositionLocalOf và so số composable recompose.', 'Run with compositionLocalOf, then switch to staticCompositionLocalOf and compare how many composables recompose.')
    m('ctl.kind', 'Cách tạo LocalColor', 'How LocalColor is created')
    m('ctl.kind.dynamic', 'compositionLocalOf (theo dõi lần đọc)', 'compositionLocalOf (tracks reads)')
    m('ctl.kind.static', 'staticCompositionLocalOf (không theo dõi)', 'staticCompositionLocalOf (no tracking)')
    m('diagramTitle', 'Cây composable với một CompositionLocalProvider', 'A composable tree with one CompositionLocalProvider')
    m('diagramDesc', 'C1 có một nhánh C2, C4, C6 và một nhánh là provider của LocalColor với C3, C5, C7, C8; C3 và C8 đọc giá trị', 'C1 has one branch C2, C4, C6 and another, the LocalColor provider with C3, C5, C7, C8; C3 and C8 read the value')
    for k, vi, en in [('c1', 'C1 (giữ dark)', 'C1 (holds dark)'), ('c2', 'C2', 'C2'), ('c4', 'C4', 'C4'), ('c6', 'C6 đọc (nhánh khác)', 'C6 reads (other branch)'), ('prov', 'CompositionLocalProvider', 'CompositionLocalProvider'),
                      ('c3', 'C3 đọc LocalColor', 'C3 reads LocalColor'), ('c5', 'C5', 'C5'), ('c7', 'C7', 'C7'), ('c8', 'C8 đọc LocalColor', 'C8 reads LocalColor')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('recomposed', 'Recompose trong content', 'Recomposed in content'), ('readers', 'Nơi đọc .current', 'Places reading .current'), ('provided', 'Màu được cung cấp', 'Provided colour')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('provided', 'Provider cung cấp', 'Provider supplies'), ('c8', 'C8 thấy', 'C8 sees'), ('c6', 'C6 thấy (giá trị mặc định)', 'C6 sees (the default)')]:
        m('st.' + k, vi, en)
    m('sk.branch', 'Nhánh C2 → C4 → C6', 'The C2 → C4 → C6 branch')
    m('sk.notInside', 'không nằm trong provider; C6 luôn đọc giá trị mặc định', 'it is not inside the provider; C6 always reads the default')
    S = [
        ('first', 'Composition đầu: mỗi nhánh thấy gì', 'First composition: what each branch sees', 'Trong provider, `C3` và `C8` đọc `LocalColor.current` và nhận giá trị gần nhất được cung cấp (Peach). `C6` ở nhánh trên, không có provider nào bên trên nó, nên nhận giá trị mặc định từ `compositionLocalOf { Peach }`.', 'Inside the provider, `C3` and `C8` read `LocalColor.current` and get the nearest provided value (Peach). `C6` is in the upper branch with no provider above it, so it gets the default from `compositionLocalOf { Peach }`.'),
        ('toggle', 'Bật dark: provider cung cấp Brown', 'Dark on: the provider supplies Brown', '`C1` đọc `dark` nên chạy lại; `C2` không có tham số nên được skip; `CompositionLocalProvider` được gọi với giá trị mới.', '`C1` reads `dark`, so it re-runs; `C2` has no parameters, so it is skipped; `CompositionLocalProvider` is called with the new value.'),
        ('dynReaders', 'compositionLocalOf: chỉ C3 và C8 chạy lại', 'compositionLocalOf: only C3 and C8 re-run', 'Lần đọc `.current` được theo dõi như lần đọc state. Giá trị được cung cấp đổi thì chỉ những scope đã đọc nó bị invalidate: `C3` và `C8`. `C5` và `C7` không đọc nên được skip.', 'Reads of `.current` are tracked like state reads. When the provided value changes, only the scopes that read it are invalidated: `C3` and `C8`. `C5` and `C7` did not read it, so they are skipped.'),
        ('staticAll', 'staticCompositionLocalOf: cả content chạy lại', 'staticCompositionLocalOf: the whole content re-runs', 'Lần đọc không được theo dõi, nên runtime không biết ai đọc. Đổi giá trị làm toàn bộ content của provider recompose: `C3`, `C5`, `C7`, `C8`, kể cả hai composable không hề đọc LocalColor.', 'Reads are not tracked, so the runtime does not know who read it. Changing the value recomposes the provider\'s whole content: `C3`, `C5`, `C7`, `C8`, including the two that never read LocalColor.'),
        ('other', 'Nhánh C2 → C4 → C6 không bị ảnh hưởng', 'The C2 → C4 → C6 branch is unaffected', '`C6` không nằm dưới provider nên vẫn thấy giá trị mặc định, dù provider bên cạnh vừa đổi giá trị.', '`C6` is not under the provider, so it still sees the default, even though the neighbouring provider just changed its value.'),
        ('end.dynamic', 'Kết thúc: 2 composable recompose', 'The end: 2 composables recomposed', 'Đúng nơi cần cập nhật màu, không hơn.', 'Exactly the places that must update the colour, no more.'),
        ('end.static', 'Kết thúc: 4 composable recompose', 'The end: 4 composables recomposed', 'Với một màu đổi theo công tắc, static tốn công hơn. Với giá trị gần như không bao giờ đổi, static lại rẻ hơn vì không phải theo dõi lần đọc.', 'For a colour flipped by a switch, static costs more. For a value that almost never changes, static is cheaper because no reads have to be tracked.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('dynamic', '`compositionLocalOf`: đổi giá trị được cung cấp chỉ invalidate nội dung đã đọc nó bằng `.current`. [[src:rt-local-src]]', '`compositionLocalOf`: changing the provided value only invalidates content that read it with `.current`. [[src:rt-local-src]]'),
        ('static', 'Liên hệ chương B2: getter `skipping` ở commit ghim đòi `!providersInvalid`; khi giá trị static đổi, các composable con không được skip dù tham số giống hệt. [[src:rt-local-src]] [[src:rt-gapcomposer]]', 'A link to chapter B2: the `skipping` getter at the pinned commit requires `!providersInvalid`; when a static value changes, child composables cannot skip even with identical parameters. [[src:rt-local-src]] [[src:rt-gapcomposer]]'),
        ('end.dynamic', 'KDoc ở commit ghim: màu và giá trị theme có thể đổi hoặc được animate, nên dùng `compositionLocalOf`. [[src:rt-local-src]]', 'The KDoc at the pinned commit: colours and theme values may change or be animated, so use `compositionLocalOf`. [[src:rt-local-src]]'),
        ('end.static', 'KDoc ở commit ghim gợi ý static cho Context, font loader và giá trị chung tương tự, gần như không đổi. [[src:rt-local-src]]', 'The KDoc at the pinned commit suggests static for Context, font loaders and similar shared values that are unlikely to change. [[src:rt-local-src]]')]:
        m('co.' + k, vi, en)
    a('cap.locals', 'C1 ở gốc (trên cùng). Nhánh trái C2 → C4 → C6 nằm ngoài provider. Nhánh phải là CompositionLocalProvider, bên trong là C3 → C5 → C7, C8. Khi giá trị đổi, các node sáng lên là những composable recompose.', 'C1 is the root (top). The left branch C2 → C4 → C6 is outside the provider. The right branch is the CompositionLocalProvider, inside which is C3 → C5 → C7, C8. When the value changes, the highlighted nodes are the composables that recompose.')

    # ---------------- chương CL (mới) ----------------
    C = 'cl'
    a(C + '.title', 'CompositionLocal và slot API: truyền dữ liệu ngầm, truyền UI làm tham số', 'CompositionLocal and slot APIs: passing data implicitly, passing UI as parameters')
    a(C + '.essence',
      'Thường dữ liệu đi xuống cây qua tham số, làm phụ thuộc của composable rõ ràng. Với dữ liệu dùng rất rộng như màu, kiểu chữ, Context, việc truyền qua mọi tầng trở nên nặng nề. CompositionLocal là đối tượng có tên, gắn với một phạm vi của cây: một tổ tiên cung cấp giá trị bằng `CompositionLocalProvider`, con cháu đọc bằng `.current` mà không khai báo tham số. `MaterialTheme` dùng chính cơ chế này.\n'
      'Có hai loại: `compositionLocalOf` theo dõi lần đọc nên đổi giá trị chỉ recompose nơi đọc; `staticCompositionLocalOf` không theo dõi nên đổi giá trị recompose cả content, hợp với giá trị gần như không đổi. Tài liệu khuyên đừng lạm dụng: phụ thuộc ngầm khó lần theo; cần giá trị mặc định tốt; không dùng để truyền ViewModel.\n'
      'Phần sau chương nói về slot API: tham số kiểu `@Composable () -> Unit` để người gọi truyền chính UI vào chỗ trống, một cách đảo điều khiển thường tốt hơn CompositionLocal.',
      'Usually data flows down the tree through parameters, which makes a composable\'s dependencies explicit. For very widely used data such as colours, type styles or the Context, passing it through every level becomes cumbersome. A CompositionLocal is a named object scoped to part of the tree: an ancestor provides a value with `CompositionLocalProvider`, and descendants read it with `.current` without declaring a parameter. `MaterialTheme` uses exactly this.\n'
      'There are two kinds: `compositionLocalOf` tracks reads, so a change only recomposes the readers; `staticCompositionLocalOf` does not track them, so a change recomposes the whole content, which suits values that almost never change. The docs warn against overuse: implicit dependencies are hard to trace; a good default is needed; never use it to pass a ViewModel around.\n'
      'The end of the chapter covers slot APIs: `@Composable () -> Unit` parameters that let callers pass UI itself into a gap, a form of inversion of control that is often better than a CompositionLocal.')
    a(C + '.goal.g1', 'Đã thấy giá trị được cung cấp đổi và ai recompose', 'Saw the provided value change and who recomposed')
    a(C + '.goal.g2', 'Đã chạy một cách tạo LocalColor tới cuối', 'Ran one way of creating LocalColor to the end')
    a(C + '.sim.runtime.locals', 'Ai recompose khi đổi giá trị', 'Who recomposes on a change')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Bạn có một `LocalColor` và gọi `CompositionLocalProvider(LocalColor provides Color.Yellow) { C8() }` bên trong `C5`. Một composable `C6` ở nhánh hoàn toàn khác của cây cũng đọc `LocalColor.current`. `C6` thấy màu gì?', 'You have a `LocalColor` and call `CompositionLocalProvider(LocalColor provides Color.Yellow) { C8() }` inside `C5`. A composable `C6` in a completely different branch of the tree also reads `LocalColor.current`. Which colour does `C6` see?')
    B(C, S, 1, 'ans', 'Giá trị mặc định khai báo trong `compositionLocalOf { … }`. Giá trị chỉ có hiệu lực trong nhánh bên dưới provider; `C6` không nằm dưới provider nào. [[src:book-compose-ess]]', 'The default declared in `compositionLocalOf { … }`. A value only applies within the branch below the provider; `C6` sits under no provider. [[src:book-compose-ess]]')

    S = 'why'
    a(C + '.sec.%s.title' % S, 'Vì sao có CompositionLocal', 'Why CompositionLocal exists')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Hình dung một cây từ `Composable1` tới `Composable8`. Một state `colorState` khai báo ở `Composable1`, nhưng chỉ `Composable8` dùng tới.\nTruyền bằng tham số thì `Composable3` và `Composable5` phải nhận rồi chuyển tiếp nó, dù chẳng cần gì tới nó. Cây càng sâu càng rối. CompositionLocal cho phép khai báo dữ liệu ở nút cao nhất cần nó, và đọc ở con cháu mà không phải đi qua các tầng ở giữa [[src:book-compose-ess]].\nGiống hệ thống loa trong toà nhà: thông báo phát ở tầng trên, ai ở tầng dưới cần thì nghe, không phải chuyền tay qua từng phòng.',
      "Picture a tree from `Composable1` to `Composable8`. A `colorState` is declared in `Composable1`, but only `Composable8` uses it.\nPassing it as a parameter forces `Composable3` and `Composable5` to take it and pass it on, even though they have no use for it. The deeper the tree, the messier. CompositionLocal lets you declare the data at the highest node that needs it, and read it in descendants without going through the levels in between [[src:book-compose-ess]].\nLike a building's PA system: an announcement made upstairs is heard by whoever needs it below, without being passed hand to hand through every room.")
    B(C, S, 2, 'p', 'Tài liệu phân biệt hai thuật ngữ. Composition là bản ghi đồ thị các lần gọi hàm composable. Cây UI là cây `LayoutNode` được quá trình composition dựng và cập nhật. CompositionLocal gắn với Composition.\n`MaterialTheme` cung cấp ba CompositionLocal (`LocalColorScheme`, `LocalTypography`, `LocalShapes`); bạn đọc chúng qua `MaterialTheme.colorScheme`, `.typography`, `.shapes`. `LocalContext` là một CompositionLocal quen thuộc trên Android. Tên thường bắt đầu bằng `Local` để IDE dễ gợi ý [[src:cp-compositionlocal]].',
      'The docs distinguish two terms. The Composition is the record of the graph of composable calls. The UI tree is the tree of `LayoutNode`s built and updated by the composition process. CompositionLocal is tied to the Composition.\n`MaterialTheme` provides three CompositionLocals (`LocalColorScheme`, `LocalTypography`, `LocalShapes`); you read them through `MaterialTheme.colorScheme`, `.typography`, `.shapes`. `LocalContext` is a familiar CompositionLocal on Android. Names usually start with `Local` so the IDE can suggest them easily [[src:cp-compositionlocal]].')

    S = 'use'
    a(C + '.sec.%s.title' % S, 'Cung cấp và đọc', 'Providing and reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ba bước:\n1. Tạo khoá bằng `compositionLocalOf { mặcĐịnh }` hoặc `staticCompositionLocalOf { mặcĐịnh }`. Cả hai trả về một `ProvidableCompositionLocal`.\n2. Cung cấp giá trị cho một nhánh bằng `CompositionLocalProvider(LocalX provides giáTrị) { … }`.\n3. Đọc ở con cháu bằng `LocalX.current`. Nó trả về giá trị của provider GẦN NHẤT phía trên; không có provider nào thì trả giá trị mặc định.\nCó thể cung cấp giá trị khác nhau ở những tầng khác nhau [[src:cp-compositionlocal]] [[src:book-compose-ess]].\nQuy tắc dễ nhớ: `.current` luôn hỏi "provider gần nhất phía trên tôi nói gì?".',
      'Three steps:\n1. Create a key with `compositionLocalOf { default }` or `staticCompositionLocalOf { default }`. Both return a `ProvidableCompositionLocal`.\n2. Provide a value for a branch with `CompositionLocalProvider(LocalX provides value) { … }`.\n3. Read it in descendants with `LocalX.current`. It returns the value of the NEAREST provider above; with no provider, the default.\nDifferent values can be provided at different levels [[src:cp-compositionlocal]] [[src:book-compose-ess]].\nRule of thumb: `.current` always asks "what does the nearest provider above me say?".')
    B(C, S, 2, 'kt', '// Rút gọn: mỗi tầng cung cấp một màu khác\nval LocalColor = staticCompositionLocalOf { Color(0xFFffdbcf) }\n\n@Composable\nfun Composable3() {\n    Text("Composable 3", Modifier.background(LocalColor.current))\n    CompositionLocalProvider(LocalColor provides Color.Red) { Composable5() }\n}\n\n@Composable\nfun Composable5() {\n    Text("Composable 5", Modifier.background(LocalColor.current))      // Red\n    CompositionLocalProvider(LocalColor provides Color.Green) { Composable7() }\n    CompositionLocalProvider(LocalColor provides Color.Yellow) { Composable8() }\n}', '// Essentials, condensed: each level provides a different colour\nval LocalColor = staticCompositionLocalOf { Color(0xFFffdbcf) }\n\n@Composable\nfun Composable3() {\n    Text("Composable 3", Modifier.background(LocalColor.current))\n    CompositionLocalProvider(LocalColor provides Color.Red) { Composable5() }\n}\n\n@Composable\nfun Composable5() {\n    Text("Composable 5", Modifier.background(LocalColor.current))      // Red\n    CompositionLocalProvider(LocalColor provides Color.Green) { Composable7() }\n    CompositionLocalProvider(LocalColor provides Color.Yellow) { Composable8() }\n}')
    B(C, S, 3, 'ask', 'Trong đoạn trên, `Composable3` thấy màu gì, `Composable7` thấy màu gì?', 'In the code above, which colour does `Composable3` see, and `Composable7`?')
    B(C, S, 3, 'ans', '`Composable3`: giá trị của provider phía trên nó (trong ví dụ đầy đủ là màu theo chế độ sáng/tối do `Composable1` cung cấp). `Provider` bên trong `Composable3` chỉ áp cho `Composable5`. `Composable7`: Green, provider gần nhất.', '`Composable3`: the value of the provider above it (in the full example, the light/dark colour provided by `Composable1`). The provider inside `Composable3` only applies to `Composable5`. `Composable7`: Green, the nearest provider.')

    S = 'kinds'
    a(C + '.sec.%s.title' % S, 'compositionLocalOf hay staticCompositionLocalOf', 'compositionLocalOf or staticCompositionLocalOf')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`compositionLocalOf`: đổi giá trị được cung cấp trong lúc recompose chỉ invalidate những nội dung đọc giá trị qua `.current`.\n`staticCompositionLocalOf`: lần đọc KHÔNG được theo dõi. Đổi giá trị làm toàn bộ content lambda nơi giá trị được cung cấp phải recompose, chứ không chỉ những chỗ đọc. Đổi lại, không phải theo dõi thì rẻ hơn khi giá trị gần như không đổi [[src:cp-compositionlocal]] [[src:rt-local-src]].',
      '`compositionLocalOf`: changing the provided value during recomposition only invalidates content that reads it via `.current`.\n`staticCompositionLocalOf`: reads are NOT tracked. Changing the value forces the entire content lambda where it is provided to recompose, not just the places that read it. In exchange, skipping the tracking is cheaper when the value almost never changes [[src:cp-compositionlocal]] [[src:rt-local-src]].')
    B(C, S, 2, 'p', 'KDoc ở commit ghim đưa ví dụ cụ thể. Context, font loader và các giá trị dùng chung tương tự gần như không đổi trong content, nên cân nhắc `staticCompositionLocalOf`. Còn màu hay giá trị kiểu theme có thể đổi, thậm chí được animate, nên dùng `compositionLocalOf`.\nNeil Smyth chọn `staticCompositionLocalOf` cho màu, với lý do màu ít đổi; KDoc thì khuyên ngược lại cho màu. Mô phỏng ngay dưới cho thấy cái giá khi một giá trị static thật sự đổi [[src:rt-local-src]] [[src:book-compose-ess]].',
      'The KDoc at the pinned commit gives concrete examples. The Context, font loaders and similar shared values hardly ever change within the content, so consider `staticCompositionLocalOf`. Colours or theme-like values may change, even be animated, so use `compositionLocalOf`.\nNeil Smyth picks `staticCompositionLocalOf` for a colour, on the grounds that colours rarely change; the KDoc advises the opposite for colours. The simulation just below shows the cost when a static value really does change [[src:rt-local-src]] [[src:book-compose-ess]].')
    B(C, S, 3, 'predict', 'Trong mô phỏng, với `compositionLocalOf` thì khi bật dark có mấy composable trong content của provider recompose? Với static thì sao?', 'In the simulation, with `compositionLocalOf`, how many composables in the provider\'s content recompose when dark is switched on? With static?')
    B(C, S, 3, 'ans', '`compositionLocalOf`: 2 (`C3` và `C8`, hai nơi đọc). Static: 4 (`C3`, `C5`, `C7`, `C8`), vì không ai biết ai đã đọc nên cả content phải chạy lại.', '`compositionLocalOf`: 2 (`C3` and `C8`, the two readers). Static: 4 (`C3`, `C5`, `C7`, `C8`), because nobody knows who read it, so the whole content must re-run.')

    S = 'decide'
    a(C + '.sec.%s.title' % S, 'Khi nào nên, khi nào không', 'When to use it, and when not')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tài liệu khuyên đừng lạm dụng. CompositionLocal tạo ra phụ thuộc ngầm:\n• Người gọi phải biết mọi giá trị cần được cung cấp.\n• Không có nguồn sự thật rõ ràng, vì giá trị có thể bị đổi ở bất kỳ tầng nào.\n• Debug phải lần ngược lên cây xem giá trị được cung cấp ở đâu (Find usages và Layout Inspector giúp được).\nNó hợp lý khi đủ hai điều kiện: có một giá trị mặc định TỐT (nếu không, test và preview lúc nào cũng phải cung cấp nó); và khái niệm thật sự gắn với cả cây hay một nhánh, mà con cháu nào cũng có thể dùng, chứ không chỉ vài cái [[src:cp-compositionlocal]].\nQuy tắc dễ nhớ: theme, Context thì hợp với CompositionLocal; dữ liệu của một màn hình thì không.',
      "The docs advise against overuse. A CompositionLocal creates hidden dependencies:\n• Callers must know every value that has to be provided.\n• There is no clear source of truth, because the value can be changed at any level.\n• Debugging means walking up the tree to find where the value was provided (Find usages and the Layout Inspector help).\nIt is reasonable when two conditions hold: there is a GOOD default value (otherwise tests and previews always have to provide it); and the concept is truly tied to the whole tree or a branch, potentially used by any descendant, not just a few [[src:cp-compositionlocal]].\nRule of thumb: themes and the Context suit CompositionLocal; one screen's data does not.")
    B(C, S, 2, 'p', 'Ví dụ xấu mà tài liệu nêu: tạo một CompositionLocal giữ ViewModel của một màn hình, để mọi composable trong màn hình lấy được. Không phải composable nào cũng cần biết ViewModel. Hãy chỉ truyền cho mỗi composable thứ nó cần, theo UDF (SH "Quản lý state").\nHai cách thay thế: truyền tham số tường minh (và chỉ phần dữ liệu cần, không truyền cả đối tượng); hoặc đảo điều khiển: tổ tiên làm việc, con chỉ báo sự kiện hoặc nhận nội dung làm tham số [[src:cp-compositionlocal]].',
      'A bad practice the docs name: a CompositionLocal holding a screen\'s ViewModel, so every composable on the screen can grab it. Not every composable needs to know about the ViewModel. Pass each composable only what it needs, following UDF (SH "Managing state").\nTwo alternatives: explicit parameters (and only the data needed, not the whole object); or inversion of control: the ancestor does the work, and the child only reports events or receives content as a parameter [[src:cp-compositionlocal]].')

    S = 'slots'
    a(C + '.sec.%s.title' % S, 'Slot API: truyền chính UI làm tham số', 'Slot APIs: passing UI itself as a parameter')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Một composable bình thường có nội dung cố định. Dù thêm tham số cho chữ hay màu, nó vẫn luôn là, chẳng hạn, một Column chứa ba `Text`.\nSlot API để trống một hay vài chỗ, như một tờ mẫu có ô trống. Composable nhận tham số kiểu `@Composable () -> Unit` và gọi nó ở chỗ trống. Người gọi quyết định thứ gì nằm ở đó. Cú pháp lambda cuối giúp gọi gọn khi chỉ có một slot [[src:book-compose-ess]].\nQuy tắc dễ nhớ: muốn người gọi tự chọn "nội dung bên trong" thì mở một slot.',
      'An ordinary composable has fixed content. Even with parameters for the text or colour, it is always, say, a Column with three `Text`s.\nA slot API leaves one or more gaps, like a form with blank boxes. The composable takes a parameter of type `@Composable () -> Unit` and calls it in the gap. The caller decides what goes there. Trailing-lambda syntax keeps the call short when there is only one slot [[src:book-compose-ess]].\nRule of thumb: to let the caller choose "what goes inside", open a slot.')
    B(C, S, 2, 'kt', '@Composable\nfun SlotDemo(\n    topContent: @Composable () -> Unit,\n    middleContent: @Composable () -> Unit,\n    bottomContent: @Composable () -> Unit\n) {\n    Column {\n        topContent()\n        middleContent()\n        bottomContent()\n    }\n}\n\nSlotDemo(\n    topContent = { Text("Top Text") },\n    middleContent = { Button(onClick = { }) { Text("Click Me") } },\n    bottomContent = { Text("Bottom Text") }\n)')
    B(C, S, 3, 'p', 'Bạn đã dùng slot API suốt mà không để ý: `Button(onClick) { Text(…) }` nhận nội dung của nút; `Scaffold` có `topBar`, `bottomBar`, `floatingActionButton`.\nTài liệu CompositionLocal coi content lambda là một cách đảo điều khiển. Thay vì con nhận một phụ thuộc (như ViewModel) để tự làm, tổ tiên dựng sẵn nội dung rồi truyền vào. Nhờ vậy con ít phụ thuộc hơn và dễ dùng lại hơn [[src:cp-compositionlocal]] [[src:book-compose-ess]].',
      "You have been using slot APIs all along without noticing: `Button(onClick) { Text(…) }` takes the button's content; `Scaffold` has `topBar`, `bottomBar`, `floatingActionButton`.\nThe CompositionLocal docs treat a content lambda as inversion of control. Instead of the child taking a dependency (such as a ViewModel) to do the work itself, the ancestor builds the content and passes it in. So the child has fewer dependencies and is easier to reuse [[src:cp-compositionlocal]] [[src:book-compose-ess]].")

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Kéo thanh trượt "độ sáng" của theme thì cả màn hình giật, Layout Inspector cho thấy mọi composable recompose mỗi lần kéo.', 'Dragging the theme\'s "brightness" slider makes the whole screen stutter; Layout Inspector shows every composable recomposing on each drag step.')
    B(C, S, 1, 'cause', 'Màu theme được cung cấp qua `staticCompositionLocalOf`. Giá trị đổi liên tục, và mỗi lần đổi, toàn bộ content của provider (gần như cả app) recompose.', 'The theme colour is provided through `staticCompositionLocalOf`. The value changes continuously, and each change recomposes the provider\'s whole content (nearly the whole app).')
    B(C, S, 1, 'fix', 'Dùng `compositionLocalOf` cho giá trị có thể đổi hoặc animate, như KDoc khuyên. [[src:rt-local-src]]', 'Use `compositionLocalOf` for values that may change or animate, as the KDoc advises. [[src:rt-local-src]]')
    B(C, S, 2, 'bug', 'Preview và test UI của một component crash với "CompositionLocal LocalUser not present".', 'Previews and UI tests of a component crash with "CompositionLocal LocalUser not present".')
    B(C, S, 2, 'cause', '`val LocalUser = compositionLocalOf<User> { error("CompositionLocal LocalUser not present") }`: không có giá trị mặc định, và preview/test không chạy trong cây có provider.', '`val LocalUser = compositionLocalOf<User> { error("CompositionLocal LocalUser not present") }`: no default, and previews/tests do not run inside a tree with a provider.')
    B(C, S, 2, 'fix', 'Truyền `user` (hoặc chỉ phần cần như `userName`) làm tham số. Nếu thật sự cần CompositionLocal, cho nó giá trị mặc định hợp lý, như tài liệu yêu cầu.', 'Pass `user` (or only what is needed, such as `userName`) as a parameter. If a CompositionLocal is truly needed, give it a sensible default, as the docs require.')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Chọn cho từng giá trị: tham số, `compositionLocalOf`, hay `staticCompositionLocalOf`? (a) khoảng cách (spacing) của design system, có thể đổi theo kích thước màn hình; (b) bộ định dạng ngày theo locale, đổi rất hiếm; (c) `userId` của màn hình hồ sơ; (d) màu nhấn được animate khi đổi theme.', 'Choose for each value: a parameter, `compositionLocalOf` or `staticCompositionLocalOf`? (a) the design system\'s spacing, which may change with screen size; (b) a locale-aware date formatter, which changes very rarely; (c) the profile screen\'s `userId`; (d) an accent colour animated when the theme changes.')
    B(C, S, 1, 'sol', '(a) `compositionLocalOf` (dùng rộng khắp, có thể đổi); (b) `staticCompositionLocalOf` (gần như không đổi, đọc ở nhiều nơi); (c) tham số: dữ liệu của một màn hình, không gắn với cây; (d) `compositionLocalOf`: animate là đổi mỗi frame, static sẽ recompose cả content mỗi frame.', '(a) `compositionLocalOf` (widely used, may change); (b) `staticCompositionLocalOf` (almost never changes, read in many places); (c) a parameter: data of one screen, not tree-scoped; (d) `compositionLocalOf`: animating means changing every frame, and static would recompose the whole content every frame.')
    B(C, S, 2, 'ex', 'Biến composable này thành slot API để người gọi tự chọn icon và nội dung phụ:', 'Turn this composable into a slot API so the caller chooses the icon and the trailing content:')
    B(C, S, 2, 'exkt', '@Composable\nfun SettingRow(title: String) {\n    Row {\n        Icon(Icons.Default.Settings, contentDescription = null)\n        Text(title, Modifier.weight(1f))\n        Switch(checked = false, onCheckedChange = null)\n    }\n}')
    B(C, S, 2, 'solkt', '@Composable\nfun SettingRow(\n    title: String,\n    leading: @Composable () -> Unit = {},\n    trailing: @Composable () -> Unit = {}\n) {\n    Row(verticalAlignment = Alignment.CenterVertically) {\n        leading()\n        Text(title, Modifier.weight(1f))\n        trailing()\n    }\n}\n\nSettingRow("Notifications", leading = { Icon(Icons.Default.Notifications, null) }) {\n    Switch(checked = notificationsOn, onCheckedChange = onNotificationsChange)\n}')
    B(C, S, 2, 'sol', 'Hàng không còn biết gì về switch hay state của nó: người gọi truyền vào, đúng tinh thần đảo điều khiển.', 'The row no longer knows anything about the switch or its state: the caller passes it in, in the spirit of inversion of control.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', '`LocalX.current` trả về giá trị nào?', 'Which value does `LocalX.current` return?')
    B(C, S, 1, 'ans', 'Giá trị của `CompositionLocalProvider` gần nhất phía trên trong cây; không có thì giá trị mặc định.', 'The value of the nearest `CompositionLocalProvider` above in the tree; if none, the default.')
    B(C, S, 2, 'ask', 'Khác biệt về recomposition giữa `compositionLocalOf` và `staticCompositionLocalOf`?', 'The recomposition difference between `compositionLocalOf` and `staticCompositionLocalOf`?')
    B(C, S, 2, 'ans', 'Dynamic theo dõi lần đọc nên chỉ nơi đọc recompose; static không theo dõi nên cả content của provider recompose.', 'Dynamic tracks reads, so only readers recompose; static does not, so the provider\'s whole content recomposes.')
    B(C, S, 3, 'ask', 'Hai điều kiện để một CompositionLocal là lựa chọn hợp lý?', 'Two conditions for a CompositionLocal to be a reasonable choice?')
    B(C, S, 3, 'ans', 'Có giá trị mặc định tốt, và khái niệm gắn với cây hay nhánh, có thể được bất kỳ con cháu nào dùng.', 'A good default value, and a concept scoped to the tree or a branch that any descendant may use.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Có nên đặt ViewModel của màn hình vào một CompositionLocal?', 'Should a screen\'s ViewModel go into a CompositionLocal?',
         'Không.', 'No.', 'Tài liệu gọi đó là thực hành xấu; chỉ truyền thứ mỗi composable cần.', 'The docs call it a bad practice; pass each composable only what it needs.'),
        ('q2', 'Màu theme có thể animate nên dùng loại CompositionLocal nào?', 'A theme colour that can animate should use which kind of CompositionLocal?',
         '`compositionLocalOf`.', '`compositionLocalOf`.', 'Static sẽ recompose cả content mỗi lần đổi.', 'Static would recompose the whole content on every change.'),
        ('q3', 'Composable ở nhánh khác (không dưới provider) đọc CompositionLocal thì nhận gì?', 'What does a composable in another branch (not under the provider) get when reading the CompositionLocal?',
         'Giá trị mặc định.', 'The default value.', 'Giá trị cung cấp chỉ có hiệu lực trong nhánh bên dưới provider.', 'A provided value only applies within the branch below the provider.'),
        ('q4', '`Scaffold(topBar = { … })` là ví dụ của khái niệm nào?', '`Scaffold(topBar = { … })` is an example of which concept?',
         'Slot API.', 'A slot API.', 'Tham số `@Composable () -> Unit` để người gọi truyền UI vào chỗ trống.', 'A `@Composable () -> Unit` parameter letting the caller pass UI into a gap.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
